async function refreshProject({showLoading=true}:{showLoading?:boolean}={}){const current=project();if(!current)return;if(showLoading)loading.value=true;try{const client=new Api(current.apiPath);const [index,repositoryResult]=await Promise.all([loadProjectTicketRefresh(client,current.id),client.repositoryStatus(current.id).then(status=>({status,error:''})).catch(reason=>({status:null,error:reason instanceof Error?reason.message:String(reason)}))]);if(project()?.id!==current.id)return;if(index.tickets){tickets.value=index.tickets;scheduleClaimLeaseExpiry();const live=new Set(index.tickets.map(ticket=>ticket.slug)),selected=selectedTicketSlugs.value.filter(slug=>live.has(slug));if(selected.length!==selectedTicketSlugs.value.length){selectedTicketSlugs.value=selected;if(ticketSelectionAnchor&&!live.has(ticketSelectionAnchor))ticketSelectionAnchor=undefined;if(selected.length!==1)selectedTicket.value=null}}corruptTickets.value=index.corruptTickets??[];if(corruptTickets.value.length===0&&selectedView.value==='errors')selectedView.value='all';if(selectedCorruptKey.value&&!corruptTickets.value.some(ticket=>corruptTicketKey(ticket)===selectedCorruptKey.value))selectedCorruptKey.value=undefined;repository.value=repositoryResult.status;repositoryError.value=repositoryResult.error;error.value=[index.ticketsError,index.corruptTicketsError].filter(Boolean).join(' · ');if(selectedTicket.value&&index.tickets){const previous=selectedTicket.value,matching=index.tickets.find(item=>item.id===previous.id);if(!matching){selectedTicket.value=null;return}const refreshed=(await client.checkoutTicket(current.id,matching.id)).ticket;if(project()?.id===current.id&&selectedTicketSlugs.value.includes(refreshed.slug))reconcileRefreshedSelected(previous,refreshed)}if(searchQuery.value.trim())void refreshTicketSearch()}catch(reason){if(project()?.id===current.id)error.value=reason instanceof Error?reason.message:String(reason)}finally{if(showLoading&&project()?.id===current.id)loading.value=false}}
async function refreshRepositoryStatus(){const current=project();if(!current||repositoryRefreshing.value)return;repositoryRefreshing.value=true;try{const status=await new Api(current.apiPath).repositoryStatus(current.id);if(project()?.id===current.id){repository.value=status;repositoryError.value='';if(document.querySelector('#repository-status-popover:popover-open'))void loadRepositoryDetail(repositoryView.value,true)}}catch(reason){if(project()?.id===current.id){repository.value=null;repositoryError.value=reason instanceof Error?reason.message:String(reason)}}finally{if(project()?.id===current.id)repositoryRefreshing.value=false}}
