const openSelect=()=>[...document.querySelectorAll<Control>('wa-select')].find(node=>node.open);
async function refreshAfterOpenSelectsClose(task:()=>Promise<void>){
  if(selectSafeProjectRefresh)return selectSafeProjectRefresh;
  if(!openSelect()){await task();return}
  const waitForClose=async()=>{for(let open=openSelect();open;open=openSelect())await new Promise<void>(resolve=>{open.addEventListener('wa-after-hide',()=>{resolve()},{once:true})})};
  selectSafeProjectRefresh=waitForClose().then(task).finally(()=>{selectSafeProjectRefresh=undefined});
  return selectSafeProjectRefresh;
}
function syncProjectChangePolls(){const live=new Set(projects.value.map(item=>item.id));for(const[id,stop]of projectChangePolls)if(!live.has(id)){stop();projectChangePolls.delete(id)}for(const current of projects.value)if(!projectChangePolls.has(current.id)){const stop=startProjectChangePoll({client:new Api(current.apiPath),refresh:async()=>{if(project()?.id===current.id)await refreshAfterOpenSelectsClose(async()=>{if(project()?.id===current.id)await refreshProject({showLoading:false})})},onEvents:async response=>{let resolved=false;for(const event of response.events.filter(item=>item.kind==='permission_resolved')){const resolution=parsePermissionResolution(event.message),key=`${current.id}:${event.id}`;if(key!==autoResolvingKey&&resolution&&permissionInbox.pending().some(item=>item.key===key)){permissionInbox.resolve(key,resolution.decision,resolution.scope);resolved=true}}if(resolved){updatePermissionTimer();permissionRevision.value+=1;persistPermissionHistory()}if(response.events.some(event=>event.kind==='permission_asked'||event.kind==='permission_resolved'))await refreshPermissions();if(response.events.some(event=>event.kind==='command_updated')&&project()?.id===current.id)await refreshCommands(current)}});projectChangePolls.set(current.id,stop)}}
async function refreshPermissions(){if(permissionPolling)return;permissionPolling=true;try{let changed=false;await Promise.all(projects.value.map(async current=>{const client=new Api(current.apiPath);const [requests,connections]=await Promise.all([client.permissions(),client.activeToolConnections().catch(()=>[])]),owned=requests.filter(request=>permissionBelongsToProject(request,connections,projects.value,current.id));if(!autoResolvingKey?.startsWith(`${current.id}:`))changed=permissionInbox.reconcile(current,owned,connections)||changed}));if(changed){updatePermissionTimer();permissionRevision.value+=1;persistPermissionHistory()}}catch{/* individual server disconnects remain represented by their last known requests */}finally{permissionPolling=false}}
