async function resolvePermission(item:PermissionItem,decision:PermissionDecision,scope:PermissionScope,automatic=false){if(autoResolvingKey===item.key)return;autoResolvingKey=item.key;try{const owning=projects.value.find(value=>value.id===item.projectId);if(!owning)return;await new Api(owning.apiPath).resolvePermission(item.id,decision,scope);permissionInbox.resolve(item.key,decision,scope,automatic);persistPermissionHistory();permissionTimer.remove(item.key);updatePermissionTimer();permissionRevision.value+=1}catch(reason){if(reason instanceof Error&&reason.message.includes('404')){await refreshPermissions()}else error.value=reason instanceof Error?reason.message:String(reason)}finally{autoResolvingKey=undefined}}
