async function applyTicketPatch(slug:string,patch:TicketPatch){
  const current=project(),ticket=tickets.value.find(item=>item.slug===slug);
  if(!current||!ticket)return false;
  const selectedBefore=selectedTicket.value?.slug===slug?selectedTicket.value:null,started=performance.now(),generation=(mutationGenerations.get(slug)??0)+1;
  let rollbackRow=ticket,rollbackSelected=selectedBefore;
  mutationGenerations.set(slug,generation);
  tickets.value=tickets.value.map(item=>item.slug===slug?projectTicketPatch(item,patch):item);
  if(selectedBefore)selectedTicket.value=projectTicketPatch(selectedBefore,patch);
  const optimistic=performance.now()-started;
  try{
    const base=selectedBefore??(await api().checkoutTicket(current.id,ticket.id)).ticket;
    let updated:FullTicket;
    try{
      updated=(await api().updateCheckoutTicket(current.id,ticket.id,base.concurrency_token?{...patch,expected_token:base.concurrency_token}:patch)).ticket;
    }catch(reason){
      if(!isTicketConcurrencyConflict(reason))throw reason;
      const remote=(await api().checkoutTicket(current.id,ticket.id)).ticket,reconciled=reconcileTicketPatch(base,remote,patch);
      rollbackRow=ticketRowFromFull(ticket,remote);rollbackSelected=remote;
      if(mutationGenerations.get(slug)!==generation)return true;
      tickets.value=tickets.value.map(item=>item.slug===slug?ticketRowFromFull(item,remote):item);
      if(selectedTicket.value?.slug===slug)reconcileRefreshedSelected(base,remote);
      const conflict=reconciled.conflicts[0];
      if(conflict){showFieldConflict(conflict);reportMutationTiming({slug,optimistic_ms:optimistic,request_ms:performance.now()-started,outcome:'rolled_back'});return false}
      if(Object.keys(reconciled.retry).length===0)updated=remote;
      else updated=(await api().updateCheckoutTicket(current.id,ticket.id,remote.concurrency_token?{...reconciled.retry,expected_token:remote.concurrency_token}:reconciled.retry)).ticket;
    }
    if(mutationGenerations.get(slug)!==generation){reportMutationTiming({slug,optimistic_ms:optimistic,request_ms:performance.now()-started,outcome:'stale'});return true}
    tickets.value=tickets.value.map(item=>item.slug===slug?ticketRowFromFull(item,updated):item);
    if(selectedTicket.value?.slug===slug)selectedTicket.value=updated;
    recordCommittedDraftBases(patch);error.value='';reportMutationTiming({slug,optimistic_ms:optimistic,request_ms:performance.now()-started,outcome:'committed'});return true;
  }catch(reason){
    if(mutationGenerations.get(slug)===generation){tickets.value=tickets.value.map(item=>item.slug===slug?rollbackRow:item);if(rollbackSelected&&selectedTicket.value?.slug===slug)selectedTicket.value=rollbackSelected;error.value=reason instanceof Error?reason.message:String(reason);reportMutationTiming({slug,optimistic_ms:optimistic,request_ms:performance.now()-started,outcome:'rolled_back'})}
    return false;
  }
}
async function updateSelected(patch:Record<string,unknown>){return selectedTicket.value?applyTicketPatch(selectedTicket.value.slug,patch):false}
function history(){const id=project()?.id??'';let value=histories.get(id);if(!value){value=new TicketHistory(ticketSnapshot,applyTicketPatch);histories.set(id,value)}return value}
function recordCommittedDraftBases(patch:TicketPatch){
  if(typeof patch.details==='string'&&detailsMode.value==='write')detailsDraftBase=patch.details;
  if(typeof patch.details==='string'&&readerDetailsMode.value==='write')readerDetailsDraftBase=patch.details;
  if(typeof patch.title==='string'&&titleEditing.value)titleDraftBase=patch.title;
  if(Object.hasOwn(patch,'blocked_reason')&&blockedReasonEditing.value)blockedReasonDraftBase=typeof patch.blocked_reason==='string'?patch.blocked_reason:'';
  if(Object.hasOwn(patch,'blocked_reason')&&readerBlockedReasonEditing.value)readerBlockedReasonDraftBase=typeof patch.blocked_reason==='string'?patch.blocked_reason:'';
  if(typeof patch.note_id==='string'&&patch.note_id===editingNoteId.value&&typeof patch.note==='string')noteDraftBase=patch.note;
  if(typeof patch.note_id==='string'&&patch.note_id===readerEditingNoteId.value&&typeof patch.note==='string')readerNoteDraftBase=patch.note;
}
