interface BulkOperation {slug:string;id:string;patch:TicketPatch}
async function applyBulkOperations(operations:BulkOperation[]){const current=project();if(!current||operations.length===0)return false;const slugs=new Set(operations.map(item=>item.slug)),before=tickets.value.filter(ticket=>slugs.has(ticket.slug)),selectedBefore=selectedTicket.value;tickets.value=tickets.value.map(ticket=>{const operation=operations.find(item=>item.slug===ticket.slug);return operation?projectTicketPatch(ticket,operation.patch):ticket});if(selectedTicket.value){const operation=operations.find(item=>item.slug===selectedTicket.value?.slug);if(operation)selectedTicket.value=projectTicketPatch(selectedTicket.value,operation.patch)}try{const updated=await new Api(current.apiPath).batchUpdateCheckoutTickets(current.id,operations.map(operation=>{const ticket=before.find(item=>item.slug===operation.slug),token=selectedBefore?.slug===operation.slug?selectedBefore.concurrency_token:ticket?.updated_at;return{id:operation.id,patch:token?{...operation.patch,expected_token:token}:operation.patch}}));if(project()?.id!==current.id)return false;tickets.value=tickets.value.map(ticket=>{const match=updated.find(item=>item.id===ticket.id);return match?ticketRowFromFull(ticket,match):ticket});const selectedUpdate=selectedTicket.value&&updated.find(item=>item.id===selectedTicket.value?.id);if(selectedUpdate)selectedTicket.value=selectedUpdate;error.value='';return true}catch(reason){tickets.value=tickets.value.map(ticket=>before.find(item=>item.slug===ticket.slug)??ticket);if(selectedBefore&&slugs.has(selectedBefore.slug))selectedTicket.value=selectedBefore;error.value=reason instanceof Error?reason.message:String(reason);return false}}
async function executeBulkTicketAction(action:BulkTicketAction,targetSlugs=selectedTicketSlugs.value){const selected=tickets.value.filter(ticket=>targetSlugs.includes(ticket.slug));if(!canBulkUpdate(selected,capabilitiesFor)){error.value='One or more selected ticket providers do not support atomic batch updates.';return false}const operations:BulkOperation[]=selected.flatMap(ticket=>{const patch=bulkTicketPatch(ticket,action);return patch?[{slug:ticket.slug,id:ticket.id,patch}]:[]});bulkTicketDialog.value=undefined;bulkTicketSlugs=[];if(operations.length===0)return true;const inverse=operations.map(operation=>{const ticket=selected.find(item=>item.slug===operation.slug)!;const keys=new Set(Object.keys(operation.patch));if('status' in operation.patch)keys.add('up_next');return{slug:operation.slug,id:operation.id,patch:Object.fromEntries([...keys].map(key=>[key,ticket[key as keyof typeof ticket]]))}});const succeeded=await applyBulkOperations(operations);if(!succeeded)return false;history().recordExternal(()=>applyBulkOperations(inverse),()=>applyBulkOperations(operations));if(action.kind==='delete'){selectedTicketSlugs.value=[];selectedTicket.value=null;ticketSelectionAnchor=undefined}return true}
function openBulkTicketDialog(kind:'add-tag'|'remove-tag'|'delete',targetSlugs=selectedTicketSlugs.value){const selected=tickets.value.filter(ticket=>targetSlugs.includes(ticket.slug));if(!canBulkUpdate(selected,capabilitiesFor))return;bulkTicketSlugs=selected.map(ticket=>ticket.slug);bulkTicketDialog.value=kind==='delete'?{kind:'delete',count:selected.length}:{kind:'tag',mode:kind==='add-tag'?'add':'remove',count:selected.length,choices:bulkTagChoices(selected)};if(kind!=='delete')queueMicrotask(()=>document.querySelector<HTMLElement>('[name="bulk-ticket-tag"]')?.focus())}
function clipboardTicket(ticket:FullTicket|WireTicketRow,loaded?:FullTicket):ClipboardTicket {const full='details' in ticket?ticket:loaded;return{id:ticket.id,slug:ticket.slug,connection_id:ticket.connection_id,native_id:ticket.native_id,title:ticket.title,details:full?.details??'',category:ticket.category??'issue',priority:ticket.priority,status:ticket.status,up_next:ticket.up_next,tags:ticket.tags,notes:full?.notes.map(note=>({kind:note.kind,text:note.text,summary:note.summary}))??[],attachments:full?.attachments.map(item=>({id:item.id,filename:item.filename}))??[]}}
function copySelection(cut:boolean){const current=project(),rows=selectedRows();if(!current||!rows.length)return;const snapshot={tickets:rows.map(ticket=>clipboardTicket(ticket,selectedTicket.value?.id===ticket.id?selectedTicket.value:undefined)),cut,source:current};clipboard=snapshot;selectedTicketSlugs.value=[...selectedTicketSlugs.value];void Promise.all(rows.map(ticket=>api().checkoutTicket(current.id,ticket.id).then(value=>value.ticket))).then(full=>{if(clipboard!==snapshot)return;snapshot.tickets=full.map(ticket=>clipboardTicket(ticket));const text=full.map(ticket=>[`${ticket.slug}: ${ticket.title}`,ticket.details,...ticket.notes.map(note=>`- ${note.text}`)].filter(Boolean).join('\n\n')).join('\n\n');void navigator.clipboard?.writeText(text).catch(()=>undefined)}).catch(reason=>{error.value=reason instanceof Error?reason.message:String(reason)})}
async function patchTransferTickets(client:Api,checkout:string,changes:Array<{id:string;status:string}>){for(const change of changes)await client.updateCheckoutTicket(checkout,change.id,{status:change.status});return true}
async function pasteSelection(){const current=project(),snapshot=clipboard;if(!current||!snapshot?.tickets.length)return;const destinationApi=api(),sourceApi=new Api(snapshot.source.apiPath),titles=tickets.value.map(ticket=>ticket.title),created:Array<{id:string;slug:string;status:string}>=[];try{for(const source of snapshot.tickets){const title=deduplicateTitle(source.title,titles);titles.push(title);let ticket=await destinationApi.createCheckoutTicket(current.id,{title,details:source.details,category:source.category,priority:source.priority,status:source.status==='deleted'?'not_started':source.status,up_next:source.up_next,tags:source.tags});created.push({id:ticket.id,slug:ticket.slug,status:ticket.status??'not_started'});for(const note of source.notes)ticket=(await destinationApi.updateCheckoutTicket(current.id,ticket.id,{note:note.text,note_kind:note.kind,note_summary:note.summary})).ticket;for(const attachment of source.attachments)ticket=await destinationApi.copyAttachment({connection_id:source.connection_id,native_id:source.native_id,attachment_id:attachment.id},{connection_id:ticket.connection_id,native_id:ticket.native_id})}if(snapshot.cut){for(const source of snapshot.tickets)await sourceApi.updateCheckoutTicket(snapshot.source.id,source.id,{status:'deleted'});clipboard=undefined}const originals=snapshot.tickets.map(ticket=>({id:ticket.id,status:ticket.status??'not_started'}));history().recordExternal(async()=>{await patchTransferTickets(destinationApi,current.id,created.map(ticket=>({id:ticket.id,status:'deleted'})));if(snapshot.cut)await patchTransferTickets(sourceApi,snapshot.source.id,originals);await refreshProject();return true},async()=>{await patchTransferTickets(destinationApi,current.id,created.map(ticket=>({id:ticket.id,status:ticket.status})));if(snapshot.cut)await patchTransferTickets(sourceApi,snapshot.source.id,originals.map(ticket=>({id:ticket.id,status:'deleted'})));await refreshProject();return true});await refreshProject();selectedTicketSlugs.value=created.map(ticket=>ticket.slug);ticketSelectionAnchor=created[0]?.slug}catch(reason){for(const ticket of created)await destinationApi.updateCheckoutTicket(current.id,ticket.id,{status:'deleted'}).catch(()=>undefined);error.value=reason instanceof Error?reason.message:String(reason);await refreshProject()}}
async function copyDraggedTickets(destination:Project,drag:{slugs:string[];source:Project}){const sourceRows=tickets.value.filter(ticket=>drag.slugs.includes(ticket.slug));if(project()?.id!==drag.source.id||sourceRows.length===0)return;const sourceApi=new Api(drag.source.apiPath),destinationApi=new Api(destination.apiPath),created:Array<{id:string;slug:string;status:string}>=[];try{const [sources,destinationRows]=await Promise.all([Promise.all(sourceRows.map(ticket=>sourceApi.checkoutTicket(drag.source.id,ticket.id).then(result=>result.ticket))),destination.id===drag.source.id?Promise.resolve(tickets.value):destinationApi.checkoutTickets(destination.id)]),titles=destinationRows.map(ticket=>ticket.title);for(const source of sources){const title=deduplicateTitle(source.title,titles);titles.push(title);let ticket=await destinationApi.createCheckoutTicket(destination.id,{title,details:source.details,category:source.category??'issue',priority:source.priority,status:['deleted','moved','archive'].includes(source.status??'')?'not_started':source.status??'not_started',up_next:source.up_next,tags:source.tags});created.push({id:ticket.id,slug:ticket.slug,status:ticket.status??'not_started'});for(const note of source.notes.filter(note=>note.kind!=='activity'))ticket=(await destinationApi.updateCheckoutTicket(destination.id,ticket.id,{note:note.text,note_kind:note.kind})).ticket;for(const attachment of source.attachments)ticket=await destinationApi.copyAttachment({connection_id:source.connection_id,native_id:source.native_id,attachment_id:attachment.id},{connection_id:ticket.connection_id,native_id:ticket.native_id})}const refreshDestination=async()=>{if(project()?.id===destination.id)await refreshProject();return true};history().recordExternal(async()=>{await patchTransferTickets(destinationApi,destination.id,created.map(ticket=>({id:ticket.id,status:'deleted'})));return refreshDestination()},async()=>{await patchTransferTickets(destinationApi,destination.id,created.map(ticket=>({id:ticket.id,status:ticket.status})));return refreshDestination()});if(project()?.id===destination.id){await refreshProject();selectedTicketSlugs.value=created.map(ticket=>ticket.slug);ticketSelectionAnchor=created[0]?.slug}showToast(`${created.length} ticket${created.length===1?'':'s'} copied to ${destination.name}.`)}catch(reason){for(const ticket of created)await destinationApi.updateCheckoutTicket(destination.id,ticket.id,{status:'deleted'}).catch(()=>undefined);error.value=reason instanceof Error?reason.message:String(reason);if(project()?.id===destination.id)await refreshProject()}}
function isEditableEvent(event:Event){return event.composedPath().some(target=>target instanceof HTMLElement&&(target.matches('input, textarea, select, wa-input, wa-textarea, wa-select, [role="textbox"], [contenteditable]:not([contenteditable="false"])')||Boolean(target.closest('wa-dialog[open]'))))}
function ticketWorkAreaFocused(){const area=document.querySelector<HTMLElement>('.app-shell__work-area'),active=document.activeElement;return Boolean(area&&active&&(active===area||area.contains(active))&&area.querySelector('[data-component="ticket-list"], [data-component="ticket-board"]'))}
function ordinaryTextSelected(){const selection=document.getSelection();return Boolean(selection&&!selection.isCollapsed&&selection.toString().length)}
async function openProject(root:string,ticketStore?:string,remember=true){loading.value=true;try{const response=await fetch('/__hotsheet/projects/open',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({root,ticketStore})});const value=await response.json() as Project&{error?:string};if(!response.ok)throw new Error(value.error||'Could not open project.');projects.value=[...projects.value.filter(item=>item.id!==value.id),value];hideVerifiedByProject.value={...hideVerifiedByProject.value,[value.id]:localStorage.getItem(`hotsheet.project.${value.id}.hide-verified-column`)==='true'};permissionAutomationByProject.value={...permissionAutomationByProject.value,[value.id]:loadPermissionAutomation(value.id)};if(selectedProjectId.value!==value.id)resetTicketComposer();selectedProjectId.value=value.id;terminalDrawerSelected.value=localStorage.getItem(`hotsheet.project.${value.id}.terminal-drawer-selection`)||'grid';if(remember)localStorage.setItem('hotsheet.open-projects',JSON.stringify(projects.value.map(item=>item.root)));projectDialogOpen.value=false;const descriptors=await new Api(value.apiPath).providers().catch(()=>[]),selected=descriptors.find(item=>item.default)??descriptors[0];defaultProviders.value={...defaultProviders.value,[value.id]:selected?{name:selected.display_name,capabilities:selected.capabilities}:undefined};providerCapabilities.value={...providerCapabilities.value,...Object.fromEntries(descriptors.map(item=>[item.connection_id,item.capabilities]))};startPermissionUpdates();syncProjectChangePolls();await Promise.all([refreshProject(),refreshCommands(value),...(terminalDrawerVisible.value?[refreshTerminalDashboard()]:[])]);if(terminalDrawerVisible.value)observeTerminalDrawer()}catch(reason){error.value=reason instanceof Error?reason.message:String(reason)}finally{loading.value=false}}
async function chooseProjectPath(name:'project-root'|'ticket-store'){try{const response=await fetch('/__hotsheet/folders/choose',{method:'POST'}),result=await response.json() as {path?:string;error?:string};if(!response.ok)throw new Error(result.error??'Could not open the folder chooser.');if(!result.path)return;const input=document.querySelector<Control>(`[name="${name}"]`);if(input){input.value=result.path;input.dispatchEvent(new Event('input',{bubbles:true}));input.focus()}}catch(reason){error.value=reason instanceof Error?reason.message:String(reason)}}
function timeline(ticket:FullTicket){return ticketTimelineEntries(ticket).map(entry=>({...entry,time:ago(entry.timestamp)}));}
function notes(ticket:FullTicket){return ticket.notes.map(note=>({id:note.id,kind:presentedNoteKind(note,ticket.notes),author:'Hot Sheet',time:ago(note.created_at),body:note.text} as const));}
function attachmentContext(ticket:FullTicket):AttachmentReferenceContext|undefined {const current=project();return current?{baseUrl:current.apiPath,checkout:current.id,ticket:ticket.slug}:undefined}
function galleryImages(ticket=selectedTicket.value):AttachmentGalleryImage[]{const current=project();if(!ticket||!current)return[];const images:AttachmentGalleryImage[]=ticket.attachments.filter(item=>isImageAttachment(item.filename)).map(item=>({id:item.id,name:item.filename,url:api().checkoutAttachmentUrl(current.id,ticket.id,item.id)})),seen=new Set(images.map(image=>`${ticket.slug}\0${image.name}`)),context=attachmentContext(ticket)!;for(const note of ticket.notes)for(const reference of attachmentReferences(note.text)){if(!isImageAttachment(reference.filename))continue;const referencedTicket=reference.ticket??ticket.slug,key=`${referencedTicket}\0${reference.filename}`,url=attachmentReferenceUrl(context,reference);if(!seen.has(key)){seen.add(key);images.push({id:`${referencedTicket}:${reference.filename}`,name:reference.filename,url})}}return images}
async function addAttachments(slug:string,files:FileList|File[]){const current=project(),ticket=tickets.value.find(item=>item.slug===slug);if(!current||!ticket||files.length===0||!canUseAttachments())return;loading.value=true;attachmentMessage.value=`Adding ${files.length} attachment${files.length===1?'':'s'}…`;try{const screened=await screenAttachmentFiles(Array.from(files));let updated:FullTicket|undefined;for(const file of screened.readable)updated=(await api().addCheckoutAttachment(current.id,ticket.id,file)).ticket;if(updated&&selectedTicket.value?.id===ticket.id)selectedTicket.value=updated;if(screened.readable.length)await refreshProject();const warning=describeUnreadableAttachments(screened.unreadable);attachmentMessage.value=warning||`${screened.readable.length} attachment${screened.readable.length===1?'':'s'} added.`;error.value=warning}catch(reason){const message=reason instanceof Error?reason.message:String(reason);attachmentMessage.value=`Attachment failed: ${message}`;error.value=message}finally{loading.value=false}}
function selectionOrder(target:Element){const column=target.closest('[data-component="ticket-board-column"]');return column?[...column.querySelectorAll<HTMLElement>('[data-action="select-ticket-row"]')].map(item=>data(item).ticketSlug!):visibleTickets().map(ticket=>ticket.slug)}
function presentTicket(ticket:FullTicket){const changed=selectedTicket.value?.id!==ticket.id;selectedCorruptKey.value=undefined;selectedTicket.value=ticket;if(changed){codeReview.value=undefined;codeReviewMessage.value='';codeReviewLoading.value=false;expandedCodeReviewCommits.value=[];readerInlineFeedbackReplies.value={};readerFeedbackChoiceSelections.value={};readerFeedbackChoiceAnchors.clear()}detailsEditGeneration+=1;readerDetailsEditGeneration+=1;detailsMode.value='preview';readerDetailsMode.value='preview';detailsDraft.value=ticket.details;readerDetailsDraft.value=ticket.details;detailsDraftBase=ticket.details;readerDetailsDraftBase=ticket.details;titleEditing.value=false;titleDraft.value=ticket.title;titleDraftBase=ticket.title;blockedReasonEditing.value=false;readerBlockedReasonEditing.value=false;blockedReasonDraft.value=ticket.blocked_reason??'';readerBlockedReasonDraft.value=ticket.blocked_reason??'';blockedReasonDraftBase=ticket.blocked_reason??'';readerBlockedReasonDraftBase=ticket.blocked_reason??'';noteDraftBase='';readerNoteDraftBase='';editingNoteId.value=undefined;readerEditingNoteId.value=undefined;fieldConflict.value=undefined;fieldConflictResolution.value='';setInspectorVisible(true);error.value='';if(inspectorTab.value==='code-review')void refreshCodeReview()}
function cancelTicketDrafts(){detailsEditGeneration+=1;readerDetailsEditGeneration+=1;detailsAutosave.cancel();readerDetailsAutosave.cancel();noteAutosave.cancel();readerNoteAutosave.cancel();blockedReasonAutosave.cancel();readerBlockedReasonAutosave.cancel();titleAutosave.cancel();tagsAutosave.cancel();fieldConflict.value=undefined;fieldConflictResolution.value=''}
function selectTickets(slug:string,intent:{range?:boolean;toggle?:boolean}={},ordered=visibleTickets().map(ticket=>ticket.slug)){const loaded=selectedTicket.value;if(isPlainTicketReselection(selectedTicketSlugs.value,loaded?.slug,slug,intent))return Promise.resolve(loaded);selectedCorruptKey.value=undefined;const next=updateTicketSelection(ordered,{anchor:ticketSelectionAnchor,selected:new Set(selectedTicketSlugs.value)},slug,intent),selected=[...next.selected];ticketSelectionAnchor=next.anchor;selectedTicketSlugs.value=selected;cancelTicketDrafts();if(selected.length!==1){selectedTicket.value=null;return Promise.resolve(undefined)}const ticket=tickets.value.find(item=>item.slug===selected[0]),current=project();if(ticket&&current)return api().checkoutTicket(current.id,ticket.id).then(result=>{if(project()?.id===current.id&&selectedTicketSlugs.value.length===1&&selectedTicketSlugs.value[0]===result.ticket.slug)presentTicket(result.ticket);return result.ticket}).catch(reason=>{error.value=reason instanceof Error?reason.message:String(reason);return undefined});return Promise.resolve(undefined)}
async function openTicketReader(slug:string,ordered?:string[]){const ticket=await selectTickets(slug,{},ordered);if(!ticket)return;inspectorTab.value='info';readerOpen.value=true}
function closeNotWorking(){notWorkingTarget.value=CLOSED_NOT_WORKING_TARGET;notWorkingNote.value='';notWorkingFiles.value=[];notWorkingSubmitting.value=false;notWorkingError.value=''}
function openNotWorking(ticket:WireTicketRow){const current=project();if(!current)return;notWorkingTarget.value={projectId:current.id,apiPath:current.apiPath,ticketId:ticket.id,slug:ticket.slug,connectionId:ticket.connection_id};notWorkingNote.value='';notWorkingFiles.value=[];notWorkingSubmitting.value=false;notWorkingError.value='';queueMicrotask(()=>document.querySelector<HTMLTextAreaElement>('[name="not-working-note"]')?.focus())}
async function addNotWorkingFiles(files:FileList|File[]){const target=notWorkingTarget.value;if(!target||!(capabilitiesFor(target.connectionId)?.attachments??true))return;const screened=await screenAttachmentFiles(Array.from(files));notWorkingFiles.value=[...notWorkingFiles.value,...screened.readable.map(file=>({id:crypto.randomUUID(),name:file.name,file}))];notWorkingError.value=describeUnreadableAttachments(screened.unreadable)}
function resetTicketComposer(){composerAttachmentEpoch+=1;activeComposerScreenings.clear();composerScreening.value=false;composerExpanded.value=false;composerTitle.value='';composerDetails.value='';composerUpNext.value=false;composerAttachments.value=[];composerAttachmentMessage.value='';composerAttachmentError.value=false;composerSubmitting.value=false}
async function addNewTicketFiles(files:FileList|File[]){const origin=project(),epoch=composerAttachmentEpoch,screening=Symbol();composerExpanded.value=true;if(!origin||!canStageNewTicketAttachments()){composerAttachmentMessage.value='The default ticket provider cannot create tickets with attachments.';composerAttachmentError.value=true;return}activeComposerScreenings.add(screening);composerScreening.value=true;composerAttachmentMessage.value='Checking attachment files…';composerAttachmentError.value=false;try{const screened=await screenAttachmentFiles(Array.from(files));if(composerAttachmentEpoch!==epoch||project()?.id!==origin.id)return;composerAttachments.value=[...composerAttachments.value,...screened.readable.map(file=>({id:crypto.randomUUID(),name:file.name,file}))];const warning=describeUnreadableAttachments(screened.unreadable);composerAttachmentMessage.value=warning;composerAttachmentError.value=Boolean(warning);requestAnimationFrame(()=>requestAnimationFrame(()=>focusQuickTicketComposerTitle(document)))}finally{activeComposerScreenings.delete(screening);if(composerAttachmentEpoch===epoch&&project()?.id===origin.id)composerScreening.value=activeComposerScreenings.size>0}}
async function submitNewTicket(){const origin=project(),provider=defaultProvider(),title=composerTitle.value.trim();if(!origin||!title||composerScreening.value||composerSubmitting.value||!(provider?.capabilities.create??true))return;const client=new Api(origin.apiPath),files=composerAttachments.value.map(item=>item.file),placement=newTicketCreationPlacement(selectedView.value,composerUpNext.value);composerSubmitting.value=true;composerAttachmentMessage.value=files.length?`Creating ticket and adding ${files.length} attachment${files.length===1?'':'s'}…`:'Creating ticket…';composerAttachmentError.value=false;try{const result=await createTicketWithAttachments(files,()=>client.createCheckoutTicket(origin.id,{title,details:composerDetails.value,category:composerCategory.value,...placement}),async(created,file)=>(await client.addCheckoutAttachment(origin.id,created.id,file)).ticket,created=>{resetTicketComposer();if(project()?.id!==origin.id)return;cancelTicketDrafts();tickets.value=[created,...tickets.value.filter(ticket=>ticket.id!==created.id)];selectedTicket.value=null;selectedTicketSlugs.value=[created.slug];ticketSelectionAnchor=created.slug;presentTicket(created);beginDetailsEdit()});const failure=describeNewTicketAttachmentFailures(result.failed);if(project()?.id!==origin.id)return;if(selectedTicket.value?.id===result.ticket.id)selectedTicket.value={...selectedTicket.value,attachments:result.ticket.attachments};if(failure){inspectorTab.value='attachments';attachmentMessage.value=failure;error.value=failure}}catch(reason){const message=reason instanceof Error?reason.message:String(reason);composerAttachmentMessage.value=`Ticket creation failed: ${message}`;composerAttachmentError.value=true;composerSubmitting.value=false}}
async function submitNotWorking(){const target=notWorkingTarget.value;if(!target||notWorkingSubmitting.value)return;const owning=projects.value.find(item=>item.id===target.projectId);if(!owning){notWorkingError.value='The project is no longer open.';return}const client=new Api(target.apiPath),capabilities=capabilitiesFor(target.connectionId),note=(capabilities?.notes??true)?notWorkingNote.value:'';notWorkingSubmitting.value=true;notWorkingError.value='';try{const current=(await client.checkoutTicket(target.projectId,target.ticketId)).ticket;let full:FullTicket=current;await submitNotWorkingReport({note,files:notWorkingFiles.value.map(item=>item.file)},{report:async(text,files)=>{full=await client.reportNotWorking(target.connectionId,target.ticketId,text,files,current.concurrency_token)}});if(project()?.id===owning.id){await refreshProject();selectedTicketSlugs.value=[target.slug];ticketSelectionAnchor=target.slug;presentTicket(full)}closeNotWorking()}catch(reason){notWorkingError.value=reason instanceof Error?reason.message:String(reason);notWorkingSubmitting.value=false}}

function ProjectDialog(){return <wa-dialog data-project-dialog label="Open project" open={projectDialogOpen.value}><form class="project-dialog" data-action="open-project-form"><p>Select a code checkout. Hot Sheet automatically uses a valid sibling <code>&lt;project&gt;.hs2</code> ticket store. Override it when the project uses another store.</p><div class="project-dialog__path"><wa-input name="project-root" label="Project folder" value="/Users/westphal/Documents/hotsheet2" required></wa-input><wa-button appearance="outlined" type="button" data-action="browse-project-path" data-path-field="project-root" aria-label="Browse for project folder" title="Browse for project folder"><LucideIcon icon={Ellipsis} name="ellipsis"/></wa-button></div><div class="project-dialog__path"><wa-input name="ticket-store" label="Ticket store (optional)" placeholder="Automatically discover &lt;project&gt;.hs2"></wa-input><wa-button appearance="outlined" type="button" data-action="browse-project-path" data-path-field="ticket-store" aria-label="Browse for ticket store" title="Browse for ticket store"><LucideIcon icon={Ellipsis} name="ellipsis"/></wa-button></div><p class="project-dialog__error" role="alert">{error.value}</p><footer><wa-button appearance="plain" type="button" data-action="cancel-open-project">Cancel</wa-button><wa-button appearance="accent" type="submit">Open project</wa-button></footer></form></wa-dialog>;}
function EmptyState(){return <section class="app-empty"><h1>Open a Hot Sheet project</h1><p>Choose a code checkout to discover its ticket sources and start working.</p><wa-button appearance="accent" data-action="add-project">Open project</wa-button></section>;}
function commandRunFor(commandId:string){return commandRuns.value.find(run=>run.command_id===commandId)}
function showCommandDialog(){queueMicrotask(()=>{const dialog=document.querySelector<HTMLDialogElement>('[data-component="command-run-dialog"], [data-component="command-cancellation-dialog"]');if(dialog&&!dialog.open)dialog.showModal()})}
function commandIcon(command:CommandDefinition):'send'|'test'|'build'{return command.program.includes('hotsheet')||command.args.some(value=>value.includes('trigger'))?'send':command.id.includes('test')||command.title.toLowerCase().includes('test')?'test':'build'}
