function clearTicketDrag(){draggedTickets=undefined;document.querySelectorAll<HTMLElement>('[data-dragging-ticket="true"]').forEach(target=>delete target.dataset.draggingTicket)}
delegate(document.body,'dragstart','[data-action="select-ticket-row"]',(event,target)=>{const source=project(),slug=data(target).ticketSlug;if(!source||!slug)return;const slugs=selectedTicketSlugs.value.includes(slug)?[...selectedTicketSlugs.value]:[slug];draggedTickets={slugs,source};const transfer=(event as DragEvent).dataTransfer;if(transfer){transfer.effectAllowed='copyMove';transfer.setData('application/x-hotsheet-tickets',slugs.join(','))}});
delegate(document.body,'dragover','[data-ticket-drop-status], [data-ticket-drop-action], [data-ticket-drop-project]',(event,target)=>{const drag=draggedTickets;if(!drag)return;const destinationProject=data(target).ticketDropProject;if(destinationProject===drag.source.id)return;event.preventDefault();(target as HTMLElement).dataset.draggingTicket='true';if((event as DragEvent).dataTransfer)(event as DragEvent).dataTransfer!.dropEffect=destinationProject||data(target).ticketDropAction?'copy':'move'});
delegate(document.body,'dragleave','[data-ticket-drop-status], [data-ticket-drop-action], [data-ticket-drop-project]',(_event,target)=>{delete (target as HTMLElement).dataset.draggingTicket});
delegate(document.body,'drop','[data-ticket-drop-status]',(event,target)=>{const drag=draggedTickets;if(!drag||project()?.id!==drag.source.id)return;event.preventDefault();event.stopPropagation();const nextStatus=data(target).ticketDropStatus,itemId=data(target).itemId,rows=tickets.value.filter(ticket=>drag.slugs.includes(ticket.slug)),eligible=rows.filter(ticket=>nextStatus==='not_started'&&itemId==='all'?['backlog','archive','deleted','moved'].includes(ticket.status??''):ticket.status!==nextStatus).map(ticket=>ticket.slug);clearTicketDrag();if(eligible.length===1)void history().execute(eligible[0],{status:nextStatus});else if(eligible.length>1)void executeBulkTicketAction({kind:'field',field:'status',value:nextStatus!},eligible)});
delegate(document.body,'drop','[data-ticket-drop-action="duplicate"]',(event)=>{const drag=draggedTickets,destination=project();if(!drag||!destination)return;event.preventDefault();event.stopPropagation();clearTicketDrag();void copyDraggedTickets(destination,drag)});
delegate(document.body,'drop','[data-ticket-drop-project]',(event,target)=>{const drag=draggedTickets,destination=projects.value.find(item=>item.id===data(target).ticketDropProject);if(!drag||!destination||destination.id===drag.source.id)return;event.preventDefault();event.stopPropagation();clearTicketDrag();void copyDraggedTickets(destination,drag)});
delegate(document.body,'dragend','[data-action="select-ticket-row"]',()=>{clearTicketDrag()});
document.addEventListener('pointerdown',event=>{const area=document.querySelector<HTMLElement>('.app-shell__work-area'),active=document.activeElement;if(area&&active instanceof HTMLElement&&(active===area||area.contains(active))&&!event.composedPath().includes(area))active.blur()},{capture:true});
document.addEventListener('keydown',event=>{const command=event.metaKey||event.ctrlKey,key=event.key.toLowerCase(),editable=isEditableEvent(event);if(!command)return;if(key==='z'&&!editable){event.preventDefault();void (event.shiftKey?history().redo():history().undo());return}const action=ticketClipboardAction({key,command,ticketWorkAreaFocused:ticketWorkAreaFocused(),editable:editable||Boolean(document.querySelector('wa-dialog[open]')),textSelected:ordinaryTextSelected(),hasTicketSelection:selectedTicketSlugs.value.length>0,hasTicketClipboard:Boolean(clipboard?.tickets.length)});if(!action)return;event.preventDefault();if(action==='copy'||action==='cut')copySelection(action==='cut');else void pasteSelection()},{capture:true});
document.addEventListener('pointerdown',event=>{if(ticketContextMenu.value&&!eventTargetsContextMenu(event))ticketContextMenu.value=undefined;if(appTabContextMenu.value&&!(event.target as Element).closest('.app-tab-context-menu'))appTabContextMenu.value=undefined;if(repositoryFileMenu.value&&!(event.target as Element).closest('[data-component="repository-file-context-menu"]'))repositoryFileMenu.value=undefined;if(attachmentMenu.value&&!(event.target as Element).closest('[data-component="attachment-context-menu"]'))attachmentMenu.value=undefined},{capture:true});
document.addEventListener('pointerdown',event=>{const target=(event.target as Element).closest<HTMLElement>('[data-action="run-command"]');if(!target)return;commandLongPressFired=false;if(commandLongPressTimer!==undefined)window.clearTimeout(commandLongPressTimer);commandLongPressTimer=window.setTimeout(()=>{commandLongPressTimer=undefined;commandLongPressFired=true;void openCommandHistory(target.dataset.itemId!)},550)});
for(const eventName of ['pointerup','pointercancel'] as const)document.addEventListener(eventName,()=>{if(commandLongPressTimer!==undefined){window.clearTimeout(commandLongPressTimer);commandLongPressTimer=undefined}});
document.addEventListener('keydown',event=>{if(attachmentGalleryUrl.value&&['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();shiftGallery(event.key==='ArrowLeft'?-1:1);return}if(event.key==='Escape'){ticketContextMenu.value=undefined;appTabContextMenu.value=undefined;repositoryFileMenu.value=undefined;attachmentMenu.value=undefined;attachmentGalleryUrl.value=undefined;magnifiedTerminalKey.value=undefined}});
delegate(document.body,'click','*',completePointerDetailsFinish);
delegateCapture(document.body,'pointerup','*',schedulePointerDetailsFinish);
delegateCapture(document.body,'pointercancel','*',schedulePointerDetailsFinish);
for(const root of JSON.parse(localStorage.getItem('hotsheet.open-projects')||'[]') as string[])void openProject(root,undefined,false);
